-- Title: iam reinvite provisioning owner after unwind
-- Kind: patch
-- Intent: iam_hybrid_owner_membership_reinvite
-- Context: TH-01 — Admin gửi lại/đổi email Owner Invitation trên tenant provisioning; reuse cùng invitation row (không expire+insert)
-- Touches: iam.reinvite_provisioning_owner
-- Safety: idempotent; medium
-- Depends on: 006_iam_onboarding_owner_membership_with_invitation.sql, 007_iam_hybrid_owner_accept_decline_unwind.sql
-- Promoted from _drafts/008_iam_reinvite_provisioning_owner.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function iam.reinvite_provisioning_owner(
  p_tenant_id uuid,
  p_idempotency_key text,
  p_is_new_user boolean default false,
  p_owner_user_id uuid default null,
  p_owner_email text default null,
  p_owner_given_name text default null,
  p_owner_family_name text default null,
  p_owner_phone text default null,
  p_correlation_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_existing iam.idempotency_records;
  v_tenant iam.tenants;
  v_inv iam.tenant_invitations;
  v_existing_membership iam.memberships;
  v_correlation text;
  v_owner_email text;
  v_owner_email_masked text;
  v_owner_role_id uuid;
  v_invitation_id uuid;
  v_owner_user_id uuid;
  v_message_id uuid := gen_random_uuid();
  v_outcome_id uuid := gen_random_uuid();
  v_now timestamptz := now();
  v_is_new boolean := coalesce(p_is_new_user, false);
  v_prev_status text;
  v_raw_code text;
  v_code_hash text;
  v_ciphertext text;
  v_result jsonb;
begin
  if not iam.has_platform_permission('platform.tenant.create') then
    raise exception 'platform permission denied';
  end if;

  if p_tenant_id is null then
    raise exception 'VALIDATION_ERROR';
  end if;

  if p_idempotency_key is null or trim(p_idempotency_key) = '' then
    raise exception 'idempotency key required';
  end if;

  v_existing := iam._idempotency_find('tenant.owner.reinvite', 'platform', p_idempotency_key, null);
  if v_existing.idempotency_key is not null then
    return v_existing.result;
  end if;

  select * into v_tenant
  from iam.tenants t
  where t.id = p_tenant_id
  for update;

  if not found then
    raise exception 'platform tenant not found';
  end if;

  if coalesce(v_tenant.status, 'active') <> 'provisioning' then
    raise exception 'TENANT_STATE_INVALID';
  end if;

  if exists (
    select 1
    from iam.memberships m
    where m.tenant_id = p_tenant_id
      and m.is_owner is true
      and m.is_active
  ) then
    raise exception 'OWNER_ALREADY_ASSIGNED';
  end if;

  if v_is_new then
    v_owner_email := lower(trim(coalesce(p_owner_email, '')));
    if v_owner_email = '' or position('@' in v_owner_email) = 0 then
      raise exception 'owner email required';
    end if;
  else
    if p_owner_user_id is null then
      raise exception 'owner user id required';
    end if;
  end if;

  v_correlation := coalesce(nullif(trim(p_correlation_id), ''), gen_random_uuid()::text);

  if not v_is_new then
    select lower(u.email::text) into v_owner_email
    from auth.users u
    where u.id = p_owner_user_id;
    if v_owner_email is null or trim(v_owner_email) = '' then
      raise exception 'owner email required';
    end if;
    v_owner_user_id := p_owner_user_id;
  end if;

  select id into v_owner_role_id
  from iam.role_definitions
  where code = 'store_owner' and status = 'active';
  if v_owner_role_id is null then
    raise exception 'store_owner role missing';
  end if;

  select * into v_inv
  from iam.tenant_invitations i
  where i.tenant_id = p_tenant_id
    and i.is_owner is true
  order by i.created_at desc, i.id desc
  limit 1
  for update;

  if not found then
    raise exception 'OWNER_INVITATION_NOT_FOUND';
  end if;

  if v_inv.status not in ('pending', 'expired') then
    raise exception 'INVITATION_ALREADY_USED';
  end if;

  select m.* into v_existing_membership
  from iam.memberships m
  left join auth.users u on u.id = m.user_id
  left join iam.platform_user_profiles p on p.user_id = m.user_id
  where m.tenant_id = p_tenant_id
    and (
      (u.id is not null and lower(trim(u.email::text)) = v_owner_email)
      or (p.email is not null and lower(trim(p.email)) = v_owner_email)
    )
    and m.removed_at is null
  limit 1;

  if found then
    if v_existing_membership.is_active then
      raise exception 'DUPLICATE_MEMBERSHIP';
    end if;
    raise exception 'MEMBERSHIP_INACTIVE';
  end if;

  if exists (
    select 1
    from iam.tenant_invitations i
    where i.tenant_id = p_tenant_id
      and i.invitee_email = v_owner_email
      and i.status = 'pending'
      and i.id <> v_inv.id
  ) then
    raise exception 'INVITATION_PENDING_EXISTS';
  end if;

  v_prev_status := v_inv.status;
  v_raw_code := iam._generate_invitation_code();
  v_code_hash := iam._invitation_token_hash(v_raw_code);
  v_ciphertext := 'transient:' || encode(convert_to(v_raw_code, 'UTF8'), 'base64');

  update iam.tenant_invitations
  set invitee_email = v_owner_email,
      status = 'pending',
      token_hash = v_code_hash,
      expires_at = v_now + interval '7 days',
      status_changed_at = case
        when v_prev_status = 'expired' then v_now
        else status_changed_at
      end,
      version = version + 1,
      updated_at = v_now,
      delivery_correlation_id = v_correlation,
      last_sent_at = v_now,
      accepted_membership_id = null,
      target_membership_id = null
  where id = v_inv.id
  returning id into v_invitation_id;

  v_owner_email_masked :=
    left(v_owner_email, 1) || '***' ||
    substring(v_owner_email from position('@' in v_owner_email));

  perform iam.enqueue_outbox_message(
    p_tenant_id,
    'iam.email.delivery_requested',
    jsonb_build_object(
      'event_version', 1,
      'id', v_message_id,
      'occurred_on', v_now,
      'tenant_id', p_tenant_id,
      'template_id', 'activation_invitation',
      'to_email', v_owner_email,
      'correlation_id', v_correlation,
      'outcome_id', v_outcome_id,
      'locale', 'vi',
      'refs', jsonb_build_object(
        'tenant_id', p_tenant_id::text,
        'invitation_id', v_invitation_id::text
      ),
      'secret_payload_ciphertext', v_ciphertext
    ),
    v_message_id
  );

  perform iam.record_email_delivery_outcome(
    p_correlation_id := v_correlation,
    p_template_id := 'activation_invitation',
    p_status := 'queued',
    p_tenant_id := p_tenant_id,
    p_to_email_masked := v_owner_email_masked,
    p_id := v_outcome_id
  );

  v_result := jsonb_build_object(
    'tenant_id', p_tenant_id,
    'owner_membership_id', null,
    'owner_user_id', case when v_is_new then null else p_owner_user_id end,
    'tenant_status', 'provisioning',
    'correlation_id', v_correlation,
    'is_new_user', v_is_new,
    'activation_issued', true,
    'invitation_id', v_invitation_id
  );

  perform iam._idempotency_store('tenant.owner.reinvite', 'platform', p_idempotency_key, null, v_result);

  return v_result;
end;
$$;

revoke all on function iam.reinvite_provisioning_owner(
  uuid, text, boolean, uuid, text, text, text, text, text
) from public, anon;
grant execute on function iam.reinvite_provisioning_owner(
  uuid, text, boolean, uuid, text, text, text, text, text
) to authenticated;
